"""Cart pricing."""

import re

from cart.models import Line, Totals

BULK_MIN_QTY = 10
BULK_PERCENT = 10

_PERCENT_COUPON = re.compile(r"PERCENT:([0-9]+)")
_FIXED_COUPON = re.compile(r"FIXED:([0-9]+)")


def _percent_of(amount: int, percent: int) -> int:
    """`percent` of `amount` cents, rounded to a whole cent with halves rounding up."""
    return (amount * percent + 50) // 100


def _coupon_discount(coupon: str, remaining: int) -> int:
    """Discount for `coupon` applied to `remaining` cents, never more than `remaining`."""
    match = _PERCENT_COUPON.fullmatch(coupon)
    if match:
        percent = int(match.group(1))
        if not 1 <= percent <= 100:
            raise ValueError(f"percentage out of range 1..100: {percent}")
        return _percent_of(remaining, percent)

    match = _FIXED_COUPON.fullmatch(coupon)
    if match:
        return min(int(match.group(1)), remaining)

    raise ValueError(f"unknown coupon: {coupon!r}")


def price_cart(lines: list[Line], coupon: str | None = None) -> Totals:
    """Price a cart. See README.md for the discount rules."""
    subtotal = 0
    bulk_discount = 0
    for line in lines:
        if line.qty < 1:
            raise ValueError(f"quantity below 1 for {line.sku!r}: {line.qty}")
        if line.unit_cents < 0:
            raise ValueError(f"negative unit price for {line.sku!r}: {line.unit_cents}")
        amount = line.unit_cents * line.qty
        subtotal += amount
        if line.qty >= BULK_MIN_QTY:
            bulk_discount += _percent_of(amount, BULK_PERCENT)

    remaining = subtotal - bulk_discount
    coupon_discount = 0
    if coupon is not None:
        coupon_discount = _coupon_discount(coupon, remaining)

    discount = bulk_discount + coupon_discount
    return Totals(subtotal=subtotal, discount=discount, total=subtotal - discount)
